static class Tests {
 static readonly List<string> log=new List<string>();static int failures;public static string DefaultRoot(){return Program.Argument(Environment.GetCommandLineArgs(),"--test-root")??Environment.GetEnvironmentVariable("PANELOCK_TEST_ROOT")??Path.Combine(Path.GetTempPath(),"PaneLockTests");}public static string Root=DefaultRoot();public static string Reports {get{return Path.Combine(Root,"reports");}}
 static string ChromePath(){string explicitPath=Environment.GetEnvironmentVariable("PANELOCK_CHROME_PATH");if(!String.IsNullOrEmpty(explicitPath))return explicitPath;string[] roots={Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData)};foreach(var folder in roots){string candidate=Path.Combine(folder,"Google","Chrome","Application","chrome.exe");if(File.Exists(candidate))return candidate;}throw new FileNotFoundException("Chrome was not found. Set PANELOCK_CHROME_PATH for desktop tests.");}
 static void Check(bool pass,string name){log.Add((pass?"PASS ":"FAIL ")+name);if(!pass)failures++;}
 static void Pump(int milliseconds=250){var until=DateTime.UtcNow.AddMilliseconds(milliseconds);while(DateTime.UtcNow<until){Application.DoEvents();Thread.Sleep(15);}}
 static int Finish(string name){Directory.CreateDirectory(Path.Combine(Reports));File.WriteAllLines(Path.Combine(Reports,name),log);return failures==0?0:1;}
 public static int Unit(){try{
  Storage.DataDir=Path.Combine(Root,"work","v06-unit-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Storage.DataDir);
  var layout=new LayoutSettings();var area=new Rectangle(-1920,-200,1919,1080);var zones=Enumerable.Range(0,3).Select(i=>layout.Zone(area,i)).ToList();Check(zones[0].Left==area.Left&&zones[2].Right==area.Right&&zones[0].Right==zones[1].Left&&zones[1].Right==zones[2].Left,"Negative monitor coordinates and odd widths have no gaps");
  layout.Split(1,.99);Check(Math.Abs(layout.Edges[1]-(layout.Edges[2]-.15))<.0001,"Dragged divider preserves minimum pane width");layout.SetCount(2);layout.Split(1,.37);Check(layout.Zone(new Rectangle(2560,0,3840,2160),0).Width==1421,"Custom divider uses physical pixels on another monitor");
  var settings=new AppSettings();settings.Layout("A").SetCount(2);settings.Layout("A").Split(1,.4);settings.Layout("B").SetCount(3);settings.Layout("B").WorkArea=false;Storage.Write(Storage.SettingsPath,settings);string notice;var loaded=Storage.Load(out notice);Check(loaded.Layout("A").Count==2&&loaded.Layout("B").Count==3&&Math.Abs(loaded.Layout("A").Edges[1]-.4)<.0001&&!loaded.Layout("B").WorkArea,"Independent layouts and taskbar choices survive JSON round trip");
  settings.Layout("A").Split(1,.6);Storage.Write(Storage.SettingsPath,settings);File.WriteAllText(Storage.SettingsPath,"{broken");loaded=Storage.Load(out notice);Check(Math.Abs(loaded.Layout("A").Edges[1]-.4)<.0001&&notice.Contains("backup"),"Interrupted settings write recovers previous valid backup");
  var a=new MonitorInfo{Id="A",Primary=true,Bounds=new Rectangle(0,0,1920,1080),Work=new Rectangle(0,0,1920,1040)};var b=new MonitorInfo{Id="B",Bounds=new Rectangle(-3840,-100,3840,2160),Work=new Rectangle(-3840,-100,3840,2120)};var engine=new Engine(settings,new List<MonitorInfo>{a,b},null);var e=new Entry{MonitorId="B",Pane=2};Check(engine.Resolve(e.MonitorId).Id=="B","Preferred monitor selected independently of coordinates");engine.Monitors=new List<MonitorInfo>{a};Check(engine.Resolve(e.MonitorId).Id=="A"&&e.MonitorId=="B","Unplug falls back without forgetting preferred monitor");engine.Monitors.Add(b);Check(engine.Resolve(e.MonitorId).Id=="B","Reconnect returns to preferred monitor");
  settings.Windows.Add(new SavedWindow{Handle=123,Pid=42,Start=90,Title="Unique Chrome title",MonitorId="B",Pane=1});var pending=new Engine(settings,engine.Monitors,null);pending.SaveAssignments();Check(pending.Settings.Windows.Count==1&&pending.Pending.Count==1,"Unopened saved Chrome assignments are retained for later restoration");
  var exact=new LayoutSettings();exact.MinimumFraction=.15;string sizeError;
  Check(exact.SetPixels(5120,1920,0,out sizeError)&&exact.Zone(new Rectangle(0,0,5120,1440),0).Width==1600&&exact.Zone(new Rectangle(0,0,5120,1440),1).Width==1920&&exact.Zone(new Rectangle(0,0,5120,1440),2).Width==1600,"Exact middle width distributes remaining pixels equally");
  Check(exact.SetPixels(1919,901,0,out sizeError)&&exact.Zone(new Rectangle(0,0,1919,1080),1).Width==901,"Exact middle width is preserved with odd display widths");
  exact.EqualSides=false;Check(exact.SetPixels(5120,1920,1200,out sizeError)&&exact.Zone(new Rectangle(0,0,5120,1440),0).Width==1200&&exact.Zone(new Rectangle(0,0,5120,1440),2).Width==2000,"Independent side widths keep typed left and middle sizes");
  string beforeEdges=String.Join(",",exact.Edges);Check(!exact.SetPixels(5120,4900,500,out sizeError)&&String.Join(",",exact.Edges)==beforeEdges,"Impossible typed sizes are rejected without modifying layout");
  exact.EqualSides=true;exact.Split(1,.3);Check(Math.Abs(exact.Edges[1]-(1-exact.Edges[2]))<.0001,"Equal-side divider drag mirrors both sides");
  var invalid=new LayoutSettings{Count=3,Edges=new double[]{0,Double.NaN,.8,1}};invalid.Normalize();Check(invalid.Edges.All(v=>!Double.IsNaN(v))&&invalid.Edges.Length==4,"Invalid layout data resets safely");
  using(var f=new Form()){f.Text="PaneLock-OrdinaryApp-Test";f.Bounds=new Rectangle(100,100,600,450);f.Show();Pump();var h=f.Handle;uint pid;Win.GetWindowThreadProcessId(h,out pid);long start=Win.StartTime(pid);var region=Win.CreateRectRgn(5,6,450,300);Win.SetWindowRgn(h,region,true);var original=Win.RegionData(h);var p=new Win.Placement();p.length=Marshal.SizeOf(typeof(Win.Placement));Win.GetWindowPlacement(h,ref p);Win.SetWindowRgn(h,Win.CreateRectRgn(20,30,90,100),true);Check(Recovery.Restore(new RecoveryWindow{Handle=h.ToInt64(),Pid=pid,Start=start,Placement=p,Region=original})&&original.SequenceEqual(Win.RegionData(h)),"Recovery restores original non-default clipping region");Check(!Win.SameWindow(h,pid,start+1),"Reused window/process identities are rejected");
   var ordinarySettings=new AppSettings();var ordinaryEngine=new Engine(ordinarySettings,MonitorInfo.Read(),null);Check(ordinaryEngine.Assign(h,1,ordinaryEngine.MonitorFor(h).Id,true)&&!ordinaryEngine.Items[h].Chrome,"Ordinary desktop app can be assigned again");Pump();ordinaryEngine.Tick();f.WindowState=FormWindowState.Maximized;Pump();ordinaryEngine.Tick();Pump();ordinaryEngine.Tick();Pump();Check(!Win.IsZoomed(h),"Ordinary app maximize stays assigned to its pane");
   using(var owner=new Control()){var ownerHandle=owner.Handle;using(var snap=new DragSnap(ordinaryEngine,owner)){snap.ManualTests=true;Check(snap.Installed,"Native move/resize hook installs for Shift-drag");Check(snap.Begin(h,true)&&ordinaryEngine.DraggingWindow==h,"Moving a locked app temporarily suspends confinement");var m=ordinaryEngine.MonitorFor(h);var l=ordinaryEngine.LayoutFor(m);var z=l.Zone(l.WorkArea?m.Work:m.Bounds,0);var point=new Point(z.Left+z.Width/2,z.Top+40);snap.Update(true,point);Check(snap.OverlayVisible,"Shift-drag displays highlighted predefined panes");Check(snap.End(true,point)&&ordinaryEngine.Items[h].Pane==0&&ordinaryEngine.DraggingWindow==IntPtr.Zero,"Dropping with Shift assigns the app to the hovered pane");snap.Begin(h,true);snap.Update(false,point);Check(!snap.OverlayVisible&&!snap.End(false,point),"Dropping without Shift does not create a new assignment");ordinaryEngine.SetPaused(true);Check(!snap.Begin(h,true),"Paused snapping leaves window dragging alone");ordinaryEngine.SetPaused(false);}}
   ordinaryEngine.ReleaseAll();f.Close();}
 }catch(Exception ex){Check(false,"Unhandled unit test error: "+ex);}return Finish("unit-tests.txt");}
 static void ChromeBounds(Engine engine,IntPtr h,string label){var e=engine.Items[h];var z=engine.Zone(e);Win.Rect content;bool found=Engine.FindContent(h,out content);if(found)log.Add("GEOMETRY "+label+" expected="+z+" actual="+Rectangle.FromLTRB(content.L,content.T,content.R,content.B)+" dpi="+Win.GetDpiForWindow(h));Check(found&&Math.Abs(content.L-z.Left)<=2&&Math.Abs(content.T-z.Top)<=2&&Math.Abs(content.R-z.Right)<=2&&Math.Abs(content.B-z.Bottom)<=2,label);}
 public static int Desktop(){Directory.CreateDirectory(Reports);Program.TestMode=true;Storage.DataDir=Path.Combine(Root,"work","v06-desktop-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Storage.DataDir);Process chrome=null;Recovery recovery=null;Engine engine=null;IntPtr h=IntPtr.Zero;try{
  var monitors=MonitorInfo.Read();log.Add("Physical displays available: "+monitors.Count);foreach(var m in monitors)log.Add(m.Name+" "+m.Bounds+" id="+m.Id);
  string title="PaneLock-v06-"+Guid.NewGuid().ToString("N");string html=Path.Combine(Storage.DataDir,"test.html");File.WriteAllText(html,"<title>"+title+"</title><body style='background:#183565;color:white;margin:0'><h1>PaneLock workspace test</h1>");
  var start=new ProcessStartInfo(ChromePath(),"--user-data-dir=\""+Path.Combine(Storage.DataDir,"chrome-profile")+"\" --no-first-run --no-default-browser-check --force-renderer-accessibility --new-window \""+new Uri(html).AbsoluteUri+"\""){UseShellExecute=false};chrome=Process.Start(start);for(int i=0;i<70&&h==IntPtr.Zero;i++){Pump(200);h=Win.FindWindow(null,title+" - Google Chrome");}if(h==IntPtr.Zero)throw new Exception("Isolated Chrome window not found");
  var settings=new AppSettings();for(int i=0;i<monitors.Count;i++){var layout=settings.Layout(monitors[i].Id);layout.SetCount(i%2==0?3:2);if(layout.Count==3){layout.Split(1,.25);layout.Split(2,.75);}}
  recovery=new Recovery();engine=new Engine(settings,monitors,recovery);
  Check(engine.Assign(h,1,monitors[0].Id),"Assign isolated Chrome to a monitor pane");Pump(350);engine.Tick();Pump();Check(File.Exists(recovery.PathName),"Recovery journal exists before fullscreen changes");
  Check(engine.ToggleChromeFullscreen(h),"F11 enters pane fullscreen");Pump();engine.Tick();Pump();ChromeBounds(engine,h,"Chrome content fills chosen pane with custom widths");
  for(int i=1;i<monitors.Count;i++){engine.Move(h,monitors[i].Id,0);for(int wait=0;wait<12;wait++){Pump(100);engine.Tick();}Check(engine.Items[h].PaneFullscreen,"Fullscreen resumes after moving to monitor "+(i+1));ChromeBounds(engine,h,"Content fits monitor "+(i+1)+" after DPI transition");}
  if(monitors.Count>1){string preferred=engine.Items[h].MonitorId;var without=monitors.Where(m=>m.Id!=preferred).ToList();engine.UpdateMonitors(without);for(int wait=0;wait<12;wait++){Pump(100);engine.Tick();}Check(engine.Items[h].MonitorId==preferred&&engine.Items[h].ActualMonitorId!=preferred,"Monitor removal uses fallback without losing saved destination");ChromeBounds(engine,h,"Fullscreen fits fallback monitor");engine.UpdateMonitors(monitors);for(int wait=0;wait<12;wait++){Pump(100);engine.Tick();}Check(engine.Items[h].ActualMonitorId==preferred&&engine.Items[h].PaneFullscreen,"Reconnected monitor regains assigned fullscreen window");}
  var current=engine.Resolve(engine.Items[h].MonitorId);var layoutNow=settings.Layout(current.Id);layoutNow.Split(1,.45);engine.LayoutChanged(current.Id);Pump();engine.Tick();Pump();ChromeBounds(engine,h,"Fullscreen follows changed pane divider");
  using(var owner=new Control()){var handle=owner.Handle;using(var hook=new F11Hook(engine,owner)){Check(hook.Installed,"F11 keyboard hook installs");bool before=engine.Items[h].PaneFullscreen;Check(hook.RouteF11(true,false,h,false),"Assigned F11 intercepted");Pump();Check(engine.Items[h].PaneFullscreen!=before,"F11 route toggles actual Chrome");hook.RouteF11(true,false,h,false);Pump();Check(engine.Items[h].PaneFullscreen!=before,"Held key does not repeat toggle");hook.RouteF11(false,true,h,false);hook.RouteF11(true,false,h,false);Pump();hook.RouteF11(false,true,h,false);Check(engine.Items[h].PaneFullscreen==before,"Second F11 restores pane mode");Check(!hook.RouteF11(true,false,IntPtr.Zero,false)&&!hook.RouteF11(true,false,h,true),"Unassigned and modified F11 pass through");}}
  engine.SetPaused(true);Check(!engine.Items[h].PaneFullscreen,"Pause removes Chrome crop");engine.SetPaused(false);Pump();engine.Tick();
  string normalTitle=Win.Title(h);Win.SetWindowText(h,normalTitle+VideoFullscreenBridge.Marker);engine.Tick();Pump();engine.Tick();Check(engine.Items[h].PaneFullscreen&&engine.Items[h].VideoOwnsCrop,"Video fullscreen signal automatically hides Chrome toolbar");ChromeBounds(engine,h,"Video fullscreen still fills only its assigned pane");
  engine.SetPaused(true);Check(!engine.Items[h].PaneFullscreen,"Pause restores toolbar during video fullscreen");engine.SetPaused(false);Pump();engine.Tick();Check(engine.Items[h].PaneFullscreen,"Resume restores requested video fullscreen");
  Win.SetWindowText(h,normalTitle);engine.Tick();Pump();Check(!engine.Items[h].PaneFullscreen&&!engine.Items[h].VideoOwnsCrop,"Video exit signal restores Chrome toolbar automatically");
  engine.ToggleChromeFullscreen(h);Pump();Win.SetWindowText(h,normalTitle+VideoFullscreenBridge.Marker);engine.Tick();Pump();Win.SetWindowText(h,normalTitle);engine.Tick();Pump();Check(engine.Items[h].PaneFullscreen&&!engine.Items[h].VideoOwnsCrop,"Video exit preserves fullscreen enabled manually with F11");engine.ToggleChromeFullscreen(h);Pump();
  engine.SaveAssignments();Storage.Write(Storage.SettingsPath,settings);engine.ReleaseAll(false);string notice;var reopened=Storage.Load(out notice);engine=new Engine(reopened,monitors,recovery);Check(engine.RestoreAssignments(AppWindow.Read())==0&&engine.Items.ContainsKey(h),"Restart restores still-open Chrome assignment");
  var saved=reopened.Windows[0];saved.Handle=1;saved.Pid=1;saved.Start=1;engine.ReleaseAll(false);var titleSettings=new AppSettings();titleSettings.Layouts=reopened.Layouts;titleSettings.Windows.Add(saved);engine=new Engine(titleSettings,monitors,recovery);Check(engine.RestoreAssignments(AppWindow.Read())==0&&engine.Items.ContainsKey(h),"New window identity can restore by unique exact title");
  engine.ReleaseAll(false);Check(engine.Items.Count==0,"Unlock restores Chrome and clears assignments");
  var originalRegion=Win.RegionData(h);var originalPlace=new Win.Placement();originalPlace.length=Marshal.SizeOf(typeof(Win.Placement));Win.GetWindowPlacement(h,ref originalPlace);
  string childDir=Path.Combine(Storage.DataDir,"crash-child"),ready=Path.Combine(Storage.DataDir,"crash-ready.txt");Directory.CreateDirectory(childDir);var childStart=new ProcessStartInfo(Application.ExecutablePath,"--recovery-child --data \""+childDir+"\" --window "+h.ToInt64()+" --ready \""+ready+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden};using(var child=Process.Start(childStart)){for(int i=0;i<80&&!File.Exists(ready)&&!child.HasExited;i++)Pump(100);Check(File.Exists(ready)&&File.ReadAllText(ready)=="cropped","Crash test child entered pane fullscreen with watchdog active");for(int i=0;i<80&&(!child.HasExited||Directory.GetFiles(childDir,"recovery-*.json").Length>0);i++)Pump(100);Check(child.HasExited&&Directory.GetFiles(childDir,"recovery-*.json").Length==0,"Recovery helper handles forced parent termination");}
  string staged=Path.Combine(Storage.DataDir,"staged-install","PaneLock.exe");Installer.Stage(staged);Check(File.Exists(staged)&&File.Exists(Path.Combine(Path.GetDirectoryName(staged),"YouTubeCompanion","manifest.json")),"Installer stages executable and companion without external downloads");
  var afterRegion=Win.RegionData(h);Check((originalRegion==null&&afterRegion==null)||(originalRegion!=null&&afterRegion!=null&&originalRegion.SequenceEqual(afterRegion)),"Watchdog restores Chrome's exact original clipping region");var after=new Win.Placement();after.length=Marshal.SizeOf(typeof(Win.Placement));Win.GetWindowPlacement(h,ref after);Check(after.normal.L==originalPlace.normal.L&&after.normal.T==originalPlace.normal.T&&after.normal.R==originalPlace.normal.R&&after.normal.B==originalPlace.normal.B,"Watchdog restores original Chrome placement");
  // Render the real settings form with the available monitor configuration.
  engine=new Engine(settings,monitors,recovery);using(var form=new MainForm(engine,settings,recovery,false,"")){form.Show();Pump(500);using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(Reports,"interface-preview.png"));}Check(form.Visible,"Workspace form opens with monitor map and app list");
   string eventName="Local\\PaneLock.Test."+Guid.NewGuid().ToString("N");using(var activation=new InstanceActivation(eventName)){activation.Attach(form);form.Close();Check(!form.Visible&&!form.IsDisposed,"Closing settings hides it without disposing the running app");var signalStart=new ProcessStartInfo(Application.ExecutablePath,"--signal-test --name \""+eventName+"\""){UseShellExecute=false,CreateNoWindow=true};using(var launcher=Process.Start(signalStart)){for(int wait=0;wait<40&&!form.Visible;wait++)Pump(50);Check(form.Visible,"Launching again reopens the existing hidden window through IPC");launcher.WaitForExit(2000);}}form.SelectMonitor(monitors[0].Id);Pump();Check(form.Visible,"Monitor selection updates workspace UI");foreach(var display in monitors){form.Location=new Point(display.Work.Left+20,display.Work.Top+20);form.FitToMonitor();Pump(200);Check(form.ClientSize.Width>0&&form.Controls[0].Visible&&form.Bottom<=Screen.FromControl(form).WorkingArea.Bottom,"Settings window remains usable on monitor "+(monitors.IndexOf(display)+1));}form.CloseForTest();}
 }catch(Exception ex){Check(false,"Unhandled desktop test error: "+ex);}finally{if(engine!=null)try{engine.ReleaseAll(false);}catch{}if(recovery!=null)recovery.Dispose();if(h!=IntPtr.Zero)Win.PostMessage(h,0x10,IntPtr.Zero,IntPtr.Zero);if(chrome!=null)chrome.Dispose();}return Finish("chrome-integration-tests.txt");}
 public static int RecoveryChild(string[] args){try{string ready=Program.Argument(args,"--ready");IntPtr h=new IntPtr(Int64.Parse(Program.Argument(args,"--window")));Directory.CreateDirectory(Storage.DataDir);var settings=new AppSettings();var recovery=new Recovery();recovery.StartWatcher();var engine=new Engine(settings,MonitorInfo.Read(),recovery);engine.Assign(h,1,engine.MonitorFor(h).Id);Pump(400);engine.Tick();if(!recovery.WatcherRunning||!engine.ToggleChromeFullscreen(h)){File.WriteAllText(ready,"failed: watcher="+recovery.WatchStatus+" engine="+engine.Error);return 1;}Pump(250);File.WriteAllText(ready,"cropped");Process.GetCurrentProcess().Kill();return 0;}catch{return 1;}}
 public static int Demo(){var m=MonitorInfo.Read().First(x=>x.Primary);using(var f=new Form{Text="PaneLock-DragTarget",Bounds=new Rectangle(m.Work.Left+m.Work.Width/3-220,m.Work.Top+180,700,420),StartPosition=FormStartPosition.Manual}){f.Controls.Add(new Label{Dock=DockStyle.Fill,Text="Native title-bar drag test target",TextAlign=ContentAlignment.MiddleCenter});var timeout=new System.Windows.Forms.Timer{Interval=120000};timeout.Tick+=delegate{f.Close();};timeout.Start();Application.Run(f);timeout.Dispose();}return 0;}
 public static int Interactive(){Program.TestMode=true;Storage.DataDir=Path.Combine(Root,"work","v06-drag-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Storage.DataDir);string stop=Path.Combine(Root,"work","v06-stop-native-drag");if(File.Exists(stop))File.Delete(stop);var settings=new AppSettings();using(var recovery=new Recovery()){recovery.StartWatcher();var engine=new Engine(settings,MonitorInfo.Read(),recovery);using(var form=new Form{Text="PaneLock-DragController",ClientSize=new Size(420,100),StartPosition=FormStartPosition.Manual,Location=new Point(4000,1000)}){form.Controls.Add(new Label{Dock=DockStyle.Fill,Text="Testing native drag. Shift is simulated in this test build.",TextAlign=ContentAlignment.MiddleCenter});var handle=form.Handle;using(var snap=new DragSnap(engine,form)){snap.TestShift=true;var start=new ProcessStartInfo(Application.ExecutablePath,"--demo-window"){UseShellExecute=false};using(var child=Process.Start(start)){var timer=new System.Windows.Forms.Timer{Interval=100};timer.Tick+=delegate{Storage.Write(Path.Combine(Root,"work","v06-native-drag-state.json"),new{Events=snap.Events,Hit=snap.LastHit,Starts=snap.Starts,Drops=snap.Drops,Assigned=engine.Items.Count,Pane=engine.Items.Count>0?engine.Items.Values.First().Pane:-1});engine.Tick();if(File.Exists(stop))form.Close();};timer.Start();Application.Run(form);timer.Dispose();engine.ReleaseAll(false);try{child.CloseMainWindow();}catch{}}}}}return 0;}
 public static int UI(){Directory.CreateDirectory(Reports);Program.TestMode=true;Storage.DataDir=Path.Combine(Root,"work","v06-ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Storage.DataDir);var monitors=MonitorInfo.Read();var settings=new AppSettings();var primary=monitors.First(m=>m.Primary);string widthError;settings.Layout(primary.Id).SetPixels(primary.Work.Width,(int)Math.Round(primary.Work.Width*.375),0,out widthError);using(var recovery=new Recovery())using(var form=new MainForm(new Engine(settings,monitors,recovery),settings,recovery,false,"")){form.Show();Pump(500);using(var preview=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(preview,new Rectangle(Point.Empty,preview.Size));preview.Save(Path.Combine(Reports,"interface-preview.png"));}foreach(var display in monitors){form.Location=new Point(display.Work.Left+20,display.Work.Top+20);form.FitToMonitor();Pump(250);Check(form.Bottom<=Screen.FromControl(form).WorkingArea.Bottom,"Settings window fits monitor "+(monitors.IndexOf(display)+1));if(display.Work.Height<800)using(var small=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(small,new Rectangle(Point.Empty,small.Size));small.Save(Path.Combine(Reports,"interface-small-monitor.png"));}}form.CloseForTest();}return Finish("ui-scaling-tests.txt");}
